  display: flex;
  justify-content: center;
`;
const Wrapper = styled.div`
  margin-top: 20px;
  width: 90%;
  flex-direction: column;
`;
const Home = () => {
  return (
    <Container>
      <Wrapper>
      </Wrapper>
    </Container>
  );
};

export default Home;
